/* Bullsburg Money Skills: six worlds that cover the rest of Virginia's Economics and Personal Finance course
   (income and taxes, budgeting, banking, credit, insurance, college and big purchases).
   Loaded before the main game script; the game merges these into its stages, question bank and word book.
   sol = the Virginia EPF Standards of Learning each stage supports. */
var MONEY_WORLDS = [
  { n: 6, track: 'money', name: 'Paycheck Plaza', sub: 'Money World 1 · Income, jobs and taxes' },
  { n: 7, track: 'money', name: 'Budget Boulevard', sub: 'Money World 2 · Budgets and goals' },
  { n: 8, track: 'money', name: 'Bank Bay', sub: 'Money World 3 · Banking' },
  { n: 9, track: 'money', name: 'Credit Canyon', sub: 'Money World 4 · Credit and loans' },
  { n: 10, track: 'money', name: 'Safety Shores', sub: 'Money World 5 · Insurance and protection' },
  { n: 11, track: 'money', name: 'Future Falls', sub: 'Money World 6 · College, cars and real accounts' }
];

var MONEY_L = [
/* ---------------- World 6: Paycheck Plaza ---------------- */
{ id: 'pay1', world: 6, title: 'Where money comes from', sol: ['EPF.4', 'EPF.15'], terms: ['Income', 'Wages', 'Salary', 'Human capital'],
  kid: `<p>Most people get money by <strong>working</strong>. A job that pays by the hour pays <strong>wages</strong>. A job that pays the same amount every year, no matter the hours, pays a <strong>salary</strong>.</p><p>People can also earn money from a business they own, from tips, or from investments like the stocks you learn about in Stock Street.</p><p>Skills you learn, like coding, cooking or fixing cars, are called <strong>human capital</strong>. The more useful skills you have, the more people will usually pay you.</p>`,
  adult: `<p><strong>Income</strong> is money you receive. Earned income comes from work: hourly <strong>wages</strong>, an annual <strong>salary</strong>, tips, commissions or self-employment. Unearned income comes from investments, interest, rent or government benefits.</p><p>Your earning power depends heavily on <strong>human capital</strong>, the education, skills, training and credentials you bring. Jobs that need scarce skills usually pay more because demand for those workers is higher than the supply.</p>`,
  quiz: [{ q: 'You get paid $15 for every hour you work. That kind of pay is called…', o: ['Wages', 'A salary', 'A dividend', 'Interest'], why: 'Pay by the hour is wages. A salary is a fixed amount per year.' },
         { q: 'Which is an example of investing in your human capital?', o: ['Getting a certification in a skill employers want', 'Buying a new phone', 'Opening a streaming account'], why: 'Education, training and credentials raise what employers will pay you.' }] },
{ id: 'pay2', world: 6, title: 'Gross pay vs. net pay', sol: ['EPF.15'], terms: ['Gross pay', 'Net pay', 'Deductions', 'Pay stub'],
  kid: `<p>Say your job pays $500 for two weeks of work. That full amount is your <strong>gross pay</strong>.</p><p>Before the money reaches you, some is taken out for taxes and other things. Those are <strong>deductions</strong>. What's left, the money that actually lands in your account, is your <strong>net pay</strong>, sometimes called take-home pay.</p><p>Your <strong>pay stub</strong> shows both numbers and every deduction in between.</p>`,
  adult: `<p><strong>Gross pay</strong> is what you earn before anything is taken out. <strong>Net pay</strong> (take-home pay) is what you actually receive after <strong>deductions</strong>.</p><p>Common deductions: federal income tax, state income tax, Social Security and Medicare (together called FICA), plus anything you sign up for, like health insurance or retirement contributions. Your <strong>pay stub</strong> lists each one. Always budget with net pay, not gross.</p>`,
  quiz: [{ q: 'Your pay stub shows $800 gross pay and $640 net pay. How much was deducted?', o: ['$160', '$640', '$800', '$1,440'], why: '$800 − $640 = $160 in deductions.' },
         { q: 'When you make a budget, which number should you plan with?', o: ['Net pay', 'Gross pay', 'Your hourly rate'], why: 'Net pay is the money you actually get to spend or save.' }] },
{ id: 'pay3', world: 6, title: 'Taxes 101', sol: ['EPF.7', 'EPF.15'], terms: ['Income tax', 'Sales tax', 'Payroll tax', 'Progressive tax'],
  kid: `<p>Taxes pay for things everyone shares: roads, schools, fire fighters and parks.</p><p>You'll see a few kinds. <strong>Sales tax</strong> gets added when you buy things at a store. <strong>Income tax</strong> is a share of the money you earn. <strong>Payroll taxes</strong> come out of every paycheck for Social Security and Medicare.</p><p>The U.S. income tax is <strong>progressive</strong>: people who earn more pay a bigger percentage on their higher dollars.</p>`,
  adult: `<p>Federal, state and local governments raise revenue through taxes. Income tax is taken from earnings; <strong>payroll taxes</strong> (FICA) fund Social Security and Medicare; <strong>sales tax</strong> is added to purchases; property tax is paid on homes and land.</p><p>The federal income tax is <strong>progressive</strong>: higher slices of income are taxed at higher rates. A flat tax charges everyone the same rate, and a regressive tax takes a bigger share of income from lower earners, as sales taxes often do.</p>`,
  quiz: [{ q: 'In a progressive tax system…', o: ['Higher income is taxed at higher rates', 'Everyone pays the exact same dollar amount', 'Only businesses pay tax'], why: 'Progressive means the rate rises as income rises.' },
         { q: 'Social Security and Medicare are paid for mainly by…', o: ['Payroll taxes taken from paychecks', 'Sales tax at stores', 'Lottery tickets'], why: 'FICA payroll taxes fund Social Security and Medicare.' }] },
{ id: 'pay4', world: 6, title: 'Job forms: W-4 and W-2', sol: ['EPF.15'], terms: ['W-4', 'W-2', 'Withholding', 'Tax return'],
  kid: `<p>On your first day at a job you fill out a <strong>W-4</strong>. It tells your boss how much tax to hold back from each paycheck. That held-back money is called <strong>withholding</strong>.</p><p>After the year ends, your boss sends you a <strong>W-2</strong>. It shows how much you earned and how much tax was withheld.</p><p>You use the W-2 to file a <strong>tax return</strong>. If too much was withheld, you get a <strong>refund</strong>. If too little, you owe the difference.</p>`,
  adult: `<p>The <strong>W-4</strong> is the form you give your employer so it knows how much federal income tax to <strong>withhold</strong> from each check. Each January, employers send a <strong>W-2</strong> summarizing your yearly wages and the taxes withheld.</p><p>You file a <strong>tax return</strong> (usually due in mid-April) using your W-2. Withholding is a prepayment: if it was more than you owe, you get a refund; if less, you pay the balance. Freelancers and gig workers often get a 1099 instead and must set aside tax themselves.</p>`,
  quiz: [{ q: 'Which form do you fill out when you start a job so taxes are withheld correctly?', o: ['W-4', 'W-2', '1099', 'FAFSA'], why: 'The W-4 tells your employer how much to withhold.' },
         { q: 'Your employer sends you a form each January showing your wages and taxes withheld. It is the…', o: ['W-2', 'W-4', 'Pay stub', 'Lease'], why: 'The W-2 summarizes the whole year for your tax return.' }] },
{ id: 'pay5', world: 6, title: 'Benefits and careers', sol: ['EPF.4', 'EPF.15', 'EPF.18'], terms: ['Benefits', '401(k)', 'Employer match', 'Credential'],
  kid: `<p>A job pays more than just money. Many jobs also give <strong>benefits</strong>, like health insurance, paid vacation days and help saving for retirement.</p><p>Some jobs put extra money into your retirement account when you save. That's called an <strong>employer match</strong>, and it's like free money.</p><p>When you compare two jobs, look at the pay <em>and</em> the benefits.</p>`,
  adult: `<p><strong>Employee benefits</strong> are part of your total pay: health, dental and vision insurance, paid time off, and retirement plans such as a <strong>401(k)</strong>. Many employers offer an <strong>employer match</strong>, for example adding 50 cents for every dollar you save, up to a limit. Not taking the full match leaves money on the table.</p><p>Some contributions are <strong>pretax</strong>, which lowers your taxable income now. Careers that require more training or <strong>credentials</strong> often pay more over a lifetime, so weigh the cost of training against the expected income.</p>`,
  quiz: [{ q: 'Your job adds $1 to your retirement account for every $1 you save, up to 4% of your pay. This is called…', o: ['An employer match', 'A bonus tax', 'A W-2', 'Overdraft'], why: 'An employer match adds money when you save. Take the full match if you can.' },
         { q: 'Job A pays $1,000 more per year than Job B, but Job B includes health insurance worth $4,000. Which pays more in total?', o: ['Job B', 'Job A', 'They are exactly the same'], why: 'Benefits are part of your pay. Job B is worth about $3,000 more in total.' }] },
{ id: 'bpay', world: 6, boss: true, title: 'Boss: The Tax Troll', pool: ['pay1', 'pay2', 'pay3', 'pay4', 'pay5'] },

/* ---------------- World 7: Budget Boulevard ---------------- */
{ id: 'bud1', world: 7, title: 'Needs, wants and trade-offs', sol: ['EPF.1', 'EPF.10'], terms: ['Need', 'Want', 'Opportunity cost', 'Scarcity'],
  kid: `<p>A <strong>need</strong> is something you must have, like food, a place to live and clothes for school. A <strong>want</strong> is nice to have, like new sneakers or a game.</p><p>Money is limited. That's called <strong>scarcity</strong>. Every time you choose one thing, you give up the next best thing you could have bought. What you give up is the <strong>opportunity cost</strong>.</p><p>If you spend $60 on a game, the opportunity cost might be the concert ticket you can't buy now.</p>`,
  adult: `<p><strong>Scarcity</strong> means wants are unlimited but money and time are not, so every choice involves a <strong>trade-off</strong>. The <strong>opportunity cost</strong> of a decision is the value of the best alternative you give up.</p><p>Separating <strong>needs</strong> (housing, food, transportation, basic clothing) from <strong>wants</strong> helps you protect essentials first. Virginia's EPF course uses a decision grid (PACED): define the Problem, list Alternatives, set Criteria, Evaluate, and Decide.</p>`,
  quiz: [{ q: 'You choose to work Saturday instead of going to a game with friends. The opportunity cost is…', o: ['The fun of the game you gave up', 'The money you earned', 'Nothing'], why: 'Opportunity cost is the best thing you gave up to make your choice.' },
         { q: 'Which is a need?', o: ['A safe place to live', 'A new video game', 'Concert tickets', 'Designer shoes'], why: 'Housing is a need. The others are wants.' }] },
{ id: 'bud2', world: 7, title: 'Building a budget', sol: ['EPF.16'], terms: ['Budget', 'Fixed expense', 'Variable expense', '50/30/20 rule'],
  kid: `<p>A <strong>budget</strong> is a plan for your money before you spend it.</p><p>Some costs are the same every month, like a phone bill. Those are <strong>fixed expenses</strong>. Others change, like food or gas. Those are <strong>variable expenses</strong>.</p><p>A simple starting plan is <strong>50/30/20</strong>: 50% for needs, 30% for wants, 20% for savings.</p>`,
  adult: `<p>A <strong>budget</strong> tracks expected income against planned spending and saving. <strong>Fixed expenses</strong> (rent, insurance, phone plan) stay the same each month; <strong>variable expenses</strong> (groceries, gas, entertainment) change.</p><p>The <strong>50/30/20 rule</strong> is a starting guideline: 50% of net pay to needs, 30% to wants, 20% to saving and paying down debt. A budget only works if you compare it with what you actually spent and adjust.</p>`,
  quiz: [{ q: 'Using the 50/30/20 rule, how much of $2,000 net pay goes to savings?', o: ['$400', '$600', '$1,000', '$200'], why: '20% of $2,000 is $400.' },
         { q: 'Which is a variable expense?', o: ['Groceries', 'Rent', 'A fixed car payment'], why: 'Grocery spending changes month to month.' }] },
{ id: 'bud3', world: 7, title: 'The emergency fund', sol: ['EPF.16', 'EPF.17'], terms: ['Emergency fund', 'Unexpected expense', 'Liquidity'],
  kid: `<p>Cars break. Phones crack. People get sick. An <strong>emergency fund</strong> is money you set aside just for surprises like these.</p><p>Without one, people often use a credit card and end up paying extra in interest.</p><p>Keep your emergency fund somewhere safe and easy to reach, like a savings account, not in stocks that might be down when you need the money.</p>`,
  adult: `<p>An <strong>emergency fund</strong> covers unanticipated expenses or lost income. A common target is three to six months of essential expenses. Start smaller, even $500 to $1,000, and build up.</p><p>Emergency money should be <strong>liquid</strong> (quickly available without losing value), so a savings account fits better than stocks. This is why Bullsburg's graduation tips say to build an emergency fund before investing.</p>`,
  quiz: [{ q: 'Your essential expenses are $1,500 a month. A 3-month emergency fund is…', o: ['$4,500', '$1,500', '$3,000', '$18,000'], why: '$1,500 × 3 months = $4,500.' },
         { q: 'Where should an emergency fund usually be kept?', o: ['A savings account you can reach quickly', 'In one risky stock', 'Lent to a friend'], why: 'Emergency money needs to be safe and available right away.' }] },
{ id: 'bud4', world: 7, title: 'Goals and net worth', sol: ['EPF.16'], terms: ['Short-term goal', 'Long-term goal', 'Assets', 'Liabilities', 'Net worth'],
  kid: `<p>A <strong>short-term goal</strong> is something you want soon, like new headphones in two months. A <strong>long-term goal</strong> takes years, like a car or college.</p><p>To see how you're doing, add up what you own (your <strong>assets</strong>) and subtract what you owe (your <strong>liabilities</strong>). The answer is your <strong>net worth</strong>.</p>`,
  adult: `<p>Good financial goals are specific, with an amount and a deadline. Short-term goals are usually under a year; long-term goals take several years.</p><p>A <strong>net worth statement</strong> lists <strong>assets</strong> (cash, savings, investments, a car's value) and <strong>liabilities</strong> (loans, credit card balances). Net worth = assets − liabilities. Tracking it once or twice a year shows real progress.</p>`,
  quiz: [{ q: 'You have $3,000 in assets and owe $1,200. What is your net worth?', o: ['$1,800', '$4,200', '$3,000', '−$1,800'], why: '$3,000 − $1,200 = $1,800.' },
         { q: 'Which is a long-term goal?', o: ['Saving for a house down payment in 6 years', 'Buying lunch tomorrow', 'Paying this month’s phone bill'], why: 'Long-term goals take years to reach.' }] },
{ id: 'bud5', world: 7, title: 'Smart shopping', sol: ['EPF.10', 'EPF.11'], terms: ['Comparison shopping', 'Unit price', 'Impulse buy', 'Advertising'],
  kid: `<p>Before you buy, compare. Two stores may sell the same thing for different prices.</p><p>The <strong>unit price</strong> tells you the cost per ounce or per item, so you can see which size is really the better deal.</p><p>Ads are designed to make you want things fast. Waiting a day before buying something big helps you avoid an <strong>impulse buy</strong> you'll regret.</p>`,
  adult: `<p><strong>Comparison shopping</strong> means checking price, quality, warranty and reviews across sellers. The <strong>unit price</strong> (price ÷ quantity) reveals the true cost when package sizes differ.</p><p><strong>Advertising</strong> increases demand by creating urgency and appealing to emotion. Tactics like "limited time only" push impulse buys. A cooling-off rule, such as waiting 24 to 48 hours for any non-essential purchase over a set amount, protects your budget.</p>`,
  quiz: [{ q: 'A 10-ounce box costs $3.00 and a 20-ounce box costs $5.00. Which has the lower unit price?', o: ['The 20-ounce box (25¢ per ounce)', 'The 10-ounce box (30¢ per ounce)', 'They cost the same per ounce'], why: '$5.00 ÷ 20 = $0.25 per ounce, cheaper than $3.00 ÷ 10 = $0.30.' },
         { q: 'An ad says "Only 2 hours left!" What is it trying to do?', o: ['Rush you into buying before you think', 'Help you compare prices', 'Lower the price'], why: 'Urgency is a common tactic to trigger impulse buys.' }] },
{ id: 'bbud', world: 7, boss: true, title: 'Boss: The Spending Gremlin', pool: ['bud1', 'bud2', 'bud3', 'bud4', 'bud5'] },

/* ---------------- World 8: Bank Bay ---------------- */
{ id: 'bnk1', world: 8, title: 'Checking and savings', sol: ['EPF.12'], terms: ['Checking account', 'Savings account', 'Bank', 'Credit union'],
  kid: `<p>A <strong>checking account</strong> is for everyday spending. You use a debit card or an app to pay for things.</p><p>A <strong>savings account</strong> is for money you want to keep and grow. It usually pays you a little <strong>interest</strong>.</p><p>You can open accounts at a <strong>bank</strong> or a <strong>credit union</strong>. A credit union is owned by its members and often has lower fees.</p>`,
  adult: `<p><strong>Checking accounts</strong> handle daily transactions: debit card purchases, bill pay, deposits and transfers. <strong>Savings accounts</strong> hold money you don't need right away and pay interest; high-yield savings accounts usually pay more.</p><p><strong>Banks</strong> are for-profit companies owned by shareholders; <strong>credit unions</strong> are not-for-profit cooperatives owned by members, often with lower fees and loan rates. Compare fees, minimum balances, ATM access and app features before choosing.</p>`,
  quiz: [{ q: 'Which account is best for everyday spending with a debit card?', o: ['Checking account', 'Savings account', 'Retirement account'], why: 'Checking accounts are built for daily transactions.' },
         { q: 'A financial institution owned by its members is a…', o: ['Credit union', 'Stock exchange', 'Pawn shop'], why: 'Credit unions are member-owned cooperatives.' }] },
{ id: 'bnk2', world: 8, title: 'Fees and safety', sol: ['EPF.12', 'EPF.6'], terms: ['Overdraft fee', 'Monthly fee', 'FDIC', 'NCUA'],
  kid: `<p>Banks can charge <strong>fees</strong>. A common one is an <strong>overdraft fee</strong>: if you spend more than you have, the bank may charge you a fee on top of what you overspent.</p><p>Good news: your money in a bank is protected. If the bank fails, the government insurance, called <strong>FDIC</strong> for banks or <strong>NCUA</strong> for credit unions, covers up to $250,000.</p>`,
  adult: `<p>Watch for monthly maintenance fees, out-of-network ATM fees and <strong>overdraft fees</strong>, which can be charged when a purchase exceeds your balance. Many accounts waive fees with direct deposit or a minimum balance, and you can usually opt out of overdraft coverage so a purchase is simply declined.</p><p>Deposits are insured up to $250,000 per depositor, per institution, per ownership category: by the <strong>FDIC</strong> at banks and the <strong>NCUA</strong> at credit unions. Investments like stocks are not insured.</p>`,
  quiz: [{ q: 'You have $20 in checking and buy something for $25. The bank allows it and charges $35. That charge is…', o: ['An overdraft fee', 'Interest you earned', 'A dividend'], why: 'Spending more than your balance can trigger an overdraft fee.' },
         { q: 'FDIC insurance protects bank deposits up to…', o: ['$250,000 per depositor, per bank', '$1,000', 'Any amount, no limit', 'Only money in stocks'], why: 'The standard FDIC limit is $250,000 per depositor, per insured bank, per ownership category.' }] },
{ id: 'bnk3', world: 8, title: 'Debit, transfers and apps', sol: ['EPF.12'], terms: ['Debit card', 'Direct deposit', 'Electronic transfer', 'Mobile banking'],
  kid: `<p>A <strong>debit card</strong> takes money straight from your checking account. If the money isn't there, you can't spend it (or you may pay a fee).</p><p>Many jobs pay you by <strong>direct deposit</strong>: your paycheck goes right into your account.</p><p>You can send money with <strong>electronic transfers</strong> and payment apps. Only send money to people you know, because it's hard to get back.</p>`,
  adult: `<p>Common electronic transactions: debit card purchases, <strong>direct deposit</strong>, ACH transfers for bills, wire transfers and peer-to-peer apps. Debit draws directly from your checking balance, unlike a credit card, which borrows.</p><p><strong>Mobile and online banking</strong> are convenient and often cheaper; traditional branches offer in-person help. Peer-to-peer payments usually can't be reversed, so scammers favor them: never pay strangers or "prize" fees with an app.</p>`,
  quiz: [{ q: 'A debit card spends money…', o: ['Directly from your checking account', 'Borrowed from the bank', 'From your savings bonds'], why: 'Debit uses money you already have.' },
         { q: 'A stranger online asks you to send $50 by payment app to "unlock a prize." What should you do?', o: ['Don’t send it; it’s a common scam', 'Send it quickly', 'Send half'], why: 'App payments are hard to reverse, and prize fees are a classic scam.' }] },
{ id: 'bnk4', world: 8, title: 'Keeping track: reconciling', sol: ['EPF.12', 'EPF.10'], terms: ['Statement', 'Balance', 'Reconcile', 'Pending transaction'],
  kid: `<p>Every month your bank sends a <strong>statement</strong> that lists money in and money out.</p><p><strong>Reconciling</strong> means checking your own records against the statement to make sure they match. It helps you catch mistakes, forgotten subscriptions, or charges you didn't make.</p>`,
  adult: `<p>A <strong>bank statement</strong> lists deposits, withdrawals, fees and your ending <strong>balance</strong>. To <strong>reconcile</strong>, compare it with your own record, account for <strong>pending transactions</strong> that haven't posted yet, and investigate differences.</p><p>Reviewing regularly catches bank errors, duplicate charges, unwanted subscriptions and fraud early, when it's easiest to dispute.</p>`,
  quiz: [{ q: 'Your records say $300. The statement says $260, and you find a $40 purchase you forgot to write down. What happened?', o: ['Your records were missing the $40 purchase', 'The bank stole $40', 'You earned $40 interest'], why: '$300 − $40 = $260, so the statement is right.' },
         { q: 'Why reconcile your account each month?', o: ['To catch mistakes and fraud early', 'To raise your credit score', 'Banks require it to keep the account open'], why: 'Comparing records helps you spot errors and unauthorized charges.' }] },
{ id: 'bnk5', world: 8, title: 'Interest that grows', sol: ['EPF.17'], terms: ['Simple interest', 'Compound interest', 'APY', 'Rule of 72'],
  kid: `<p>When you save, the bank pays you <strong>interest</strong>.</p><p><strong>Simple interest</strong> pays only on the money you put in. <strong>Compound interest</strong> pays on your money <em>and</em> on the interest you already earned, so it snowballs over time.</p><p>The earlier you start saving, the more time your snowball has to grow.</p>`,
  adult: `<p><strong>Simple interest</strong> = principal × rate × time. <strong>Compound interest</strong> earns interest on previous interest, so growth speeds up over time. <strong>APY</strong> (annual percentage yield) shows the yearly return including compounding, so use it to compare savings accounts.</p><p>The <strong>Rule of 72</strong> estimates doubling time: divide 72 by the annual rate. At 6%, money doubles in about 12 years. Time is the most powerful ingredient, which is why starting early matters.</p>`,
  quiz: [{ q: 'Using the Rule of 72, about how long does money take to double at 8% a year?', o: ['About 9 years', 'About 72 years', 'About 8 years', 'About 4 years'], why: '72 ÷ 8 = 9 years.' },
         { q: 'Compound interest is different from simple interest because it…', o: ['Earns interest on past interest too', 'Never changes', 'Is only for loans'], why: 'Compounding means interest earns interest.' }] },
{ id: 'bbnk', world: 8, boss: true, title: 'Boss: The Fee Phantom', pool: ['bnk1', 'bnk2', 'bnk3', 'bnk4', 'bnk5'] },

/* ---------------- World 9: Credit Canyon ---------------- */
{ id: 'cr1', world: 9, title: 'What credit really is', sol: ['EPF.13'], terms: ['Credit', 'Principal', 'Interest', 'APR'],
  kid: `<p>Using <strong>credit</strong> means borrowing money now and paying it back later.</p><p>The amount you borrow is the <strong>principal</strong>. The extra you pay for borrowing is <strong>interest</strong>. The yearly cost of borrowing is called the <strong>APR</strong>.</p><p>Borrowing can help with big things, but it always costs extra, so borrow carefully.</p>`,
  adult: `<p><strong>Credit</strong> lets you buy now and pay later. You repay the <strong>principal</strong> plus <strong>interest</strong>, the price of borrowing. The <strong>APR</strong> (annual percentage rate) expresses the yearly cost, including some fees, so you can compare offers.</p><p>Ways to finance a purchase include credit cards, installment loans, store financing and "buy now, pay later" plans. Lower APR and shorter terms mean less interest paid overall.</p>`,
  quiz: [{ q: 'You borrow $1,000 and pay back $1,100. The extra $100 is…', o: ['Interest', 'Principal', 'A refund', 'A dividend'], why: 'Interest is the cost of borrowing above the principal.' },
         { q: 'To compare the cost of two loans, look at the…', o: ['APR', 'Color of the card', 'Number of letters in the lender’s name'], why: 'APR shows the yearly cost of borrowing.' }] },
{ id: 'cr2', world: 9, title: 'Credit cards', sol: ['EPF.13'], terms: ['Credit limit', 'Minimum payment', 'Grace period', 'Statement balance'],
  kid: `<p>A credit card lets you borrow up to a <strong>credit limit</strong>. Each month you get a bill.</p><p>If you pay the <strong>whole bill</strong> on time, you usually pay no interest. If you only pay the <strong>minimum payment</strong>, the rest gets charged interest, and the debt can grow for years.</p><p>Treat a credit card like a debit card: only buy what you can pay off this month.</p>`,
  adult: `<p>Credit cards are revolving credit up to a <strong>credit limit</strong>. If you pay the full <strong>statement balance</strong> by the due date, most cards charge no interest thanks to the <strong>grace period</strong>.</p><p>Paying only the <strong>minimum payment</strong> keeps the account current but leaves a balance accruing interest at the card's APR, often 20% or more, which can stretch payoff over many years. Late payments add fees and can hurt your credit score.</p>`,
  quiz: [{ q: 'What is the best way to use a credit card?', o: ['Pay the full balance every month', 'Pay only the minimum', 'Max it out to raise your limit'], why: 'Paying in full avoids interest and builds good credit.' },
         { q: 'You carry a $1,000 balance at 24% APR. About how much interest is that per month?', o: ['About $20', 'About $240', 'About $2', 'About $100'], why: '24% ÷ 12 = 2% a month, and 2% of $1,000 is about $20.' }] },
{ id: 'cr3', world: 9, title: 'Your credit score', sol: ['EPF.13'], terms: ['Credit report', 'Credit score', 'Payment history', 'Credit utilization'],
  kid: `<p>Lenders want to know if you pay back what you borrow. Your <strong>credit report</strong> is your borrowing history, and your <strong>credit score</strong> is a number that sums it up.</p><p>Scores usually run from 300 to 850. Higher is better. Paying bills <strong>on time</strong> matters most.</p><p>A good score can mean lower interest on a car, an apartment approval, and even lower insurance costs.</p>`,
  adult: `<p>Your <strong>credit report</strong>, kept by the three credit bureaus (Equifax, Experian and TransUnion), lists your accounts and payment history. Common FICO scores range from 300 to 850. The biggest factors are <strong>payment history</strong> and <strong>credit utilization</strong> (balances compared with limits; keeping it under about 30% helps), then length of history, credit mix and new applications.</p><p>You can get free reports at AnnualCreditReport.com. Landlords, lenders and some insurers and employers check credit.</p>`,
  quiz: [{ q: 'Which matters most for a strong credit score?', o: ['Paying bills on time', 'Having many credit cards', 'Your favorite color'], why: 'Payment history is the biggest factor.' },
         { q: 'Your card limit is $1,000. To keep utilization under 30%, your balance should stay under…', o: ['$300', '$900', '$30', '$3,000'], why: '30% of $1,000 is $300.' }] },
{ id: 'cr4', world: 9, title: 'Loans: car, student and more', sol: ['EPF.13'], terms: ['Secured loan', 'Unsecured loan', 'Collateral', 'Amortization'],
  kid: `<p>Some loans use something you own as a promise. If you don't pay a car loan, the lender can take the car. That's a <strong>secured loan</strong>, and the car is the <strong>collateral</strong>.</p><p>An <strong>unsecured loan</strong>, like most credit cards, has no collateral, so it usually costs more interest.</p><p>A longer loan has smaller monthly payments, but you pay more interest in total.</p>`,
  adult: `<p><strong>Secured loans</strong> (auto loans, mortgages) are backed by <strong>collateral</strong> the lender can repossess or foreclose on, so rates are usually lower. <strong>Unsecured loans</strong> (most credit cards, personal loans) carry higher rates.</p><p>An <strong>amortization schedule</strong> shows each payment split between interest and principal; early payments are mostly interest. Principal, APR, term and your credit rating together determine the payment and total cost. Longer terms lower the payment but raise total interest.</p>`,
  quiz: [{ q: 'A car loan where the lender can take the car if you stop paying is…', o: ['A secured loan', 'An unsecured loan', 'A grant'], why: 'The car is collateral, so the loan is secured.' },
         { q: 'Same loan amount and APR: a 6-year car loan compared with a 4-year loan has…', o: ['Lower payments but more total interest', 'Higher payments and less interest', 'No difference'], why: 'Stretching the term lowers each payment but adds interest overall.' }] },
{ id: 'cr5', world: 9, title: 'Getting out of debt', sol: ['EPF.13'], terms: ['Avalanche method', 'Snowball method', 'Bankruptcy', 'Credit counseling'],
  kid: `<p>If you owe money on several things, make a plan.</p><p>The <strong>avalanche method</strong> pays extra on the debt with the highest interest first, which saves the most money. The <strong>snowball method</strong> pays off the smallest debt first, so you get quick wins.</p><p>If debt gets out of control, trusted nonprofit <strong>credit counselors</strong> can help. <strong>Bankruptcy</strong> is a last resort that hurts credit for years.</p>`,
  adult: `<p>Debt strategies: the <strong>avalanche</strong> method targets the highest APR first (lowest total interest); the <strong>snowball</strong> method targets the smallest balance first (motivation from quick payoffs). Either way, keep paying minimums on everything else.</p><p>Nonprofit <strong>credit counseling</strong> can set up a debt management plan. <strong>Bankruptcy</strong> (voluntary when filed by the debtor, involuntary when creditors file) is a legal last resort; it can stay on a credit report for 7 to 10 years. Beware "debt relief" companies that charge big upfront fees.</p>`,
  quiz: [{ q: 'Which debt payoff method saves the most interest?', o: ['Paying the highest-interest debt first (avalanche)', 'Paying the smallest debt first (snowball)', 'Paying only minimums forever'], why: 'Targeting the highest APR cuts total interest the most.' },
         { q: 'Bankruptcy should be…', o: ['A last resort after other options', 'The first step when money is tight', 'A way to raise your credit score'], why: 'Bankruptcy has long-lasting effects on your credit.' }] },
{ id: 'bcr', world: 9, boss: true, title: 'Boss: The Debt Dragon', pool: ['cr1', 'cr2', 'cr3', 'cr4', 'cr5'] },

/* ---------------- World 10: Safety Shores ---------------- */
{ id: 'ins1', world: 10, title: 'Managing risk', sol: ['EPF.14'], terms: ['Risk', 'Avoid', 'Reduce', 'Transfer', 'Insurance'],
  kid: `<p>Bad things can happen: accidents, theft, illness. You can't stop all of them, but you can plan.</p><p>You can <strong>avoid</strong> a risk (don't do the risky thing), <strong>reduce</strong> it (wear a helmet), <strong>keep</strong> it (pay small costs yourself), or <strong>transfer</strong> it to someone else. Buying <strong>insurance</strong> transfers big risks to an insurance company.</p>`,
  adult: `<p>Four ways to manage risk: <strong>avoid</strong> it, <strong>reduce</strong> it (safety habits, locks, maintenance), <strong>retain</strong> it (self-insure small losses with savings) or <strong>transfer</strong> it. <strong>Insurance</strong> transfers the financial risk of large losses to an insurer in exchange for a premium.</p><p>A good rule: insure what you couldn't afford to replace or pay for yourself, and self-insure small losses with your emergency fund.</p>`,
  quiz: [{ q: 'Buying insurance is a way to…', o: ['Transfer risk to an insurance company', 'Avoid all risk forever', 'Make money quickly'], why: 'Insurance shifts the cost of big losses to the insurer.' },
         { q: 'Wearing a seat belt is an example of…', o: ['Reducing risk', 'Transferring risk', 'Retaining risk'], why: 'Safety habits lower the chance or size of a loss.' }] },
{ id: 'ins2', world: 10, title: 'Premiums and deductibles', sol: ['EPF.14'], terms: ['Premium', 'Deductible', 'Coverage', 'Claim'],
  kid: `<p>With insurance, you pay a <strong>premium</strong>, often every month, to stay covered.</p><p>When something bad happens, you file a <strong>claim</strong>. You pay the first part of the cost, called the <strong>deductible</strong>, and insurance pays the rest of what's covered.</p><p>A higher deductible usually means a lower premium, but you'll pay more when something happens.</p>`,
  adult: `<p>The <strong>premium</strong> is what you pay to keep a policy. When you file a <strong>claim</strong>, you pay the <strong>deductible</strong> first, then insurance pays covered costs up to the policy limits.</p><p>Raising the deductible usually lowers the premium. Choose a deductible you could cover from your emergency fund. Lifestyle choices (driving record, smoking, credit history in some states) can raise or lower premiums.</p>`,
  quiz: [{ q: 'Your car repair costs $2,000 and your deductible is $500. How much does insurance pay?', o: ['$1,500', '$2,000', '$500', '$2,500'], why: 'You pay the $500 deductible; insurance pays $2,000 − $500 = $1,500.' },
         { q: 'If you choose a higher deductible, your premium usually…', o: ['Goes down', 'Goes up', 'Stays exactly the same'], why: 'You take on more of the cost, so the insurer charges less.' }] },
{ id: 'ins3', world: 10, title: 'Kinds of insurance', sol: ['EPF.14'], terms: ['Auto insurance', 'Health insurance', 'Renters insurance', 'Life insurance'],
  kid: `<p><strong>Auto insurance</strong> helps pay for car accidents. Drivers are required to have it.</p><p><strong>Health insurance</strong> helps pay doctor and hospital bills. <strong>Renters insurance</strong> protects your stuff in an apartment. <strong>Life insurance</strong> pays money to your family if you die, so they can still pay the bills.</p>`,
  adult: `<p><strong>Auto insurance</strong> includes liability (damage you cause others, required by law), collision and comprehensive coverage. <strong>Health insurance</strong> covers medical costs; young adults can often stay on a parent's plan until 26.</p><p><strong>Renters insurance</strong> is inexpensive and protects belongings plus liability; <strong>homeowners insurance</strong> covers the structure too. <strong>Life insurance</strong> replaces income for dependents (term life is usually the simplest, cheapest choice). Disability insurance replaces income if you can't work.</p>`,
  quiz: [{ q: 'Which insurance protects your belongings in an apartment?', o: ['Renters insurance', 'Life insurance', 'Auto insurance'], why: 'Renters insurance covers your stuff, not the building.' },
         { q: 'Who most needs life insurance?', o: ['Someone whose family depends on their income', 'A child with no dependents', 'Nobody ever needs it'], why: 'Life insurance replaces income for people who depend on you.' }] },
{ id: 'ins4', world: 10, title: 'Protect your identity', sol: ['EPF.10', 'EPF.14'], terms: ['Identity theft', 'Phishing', 'Credit freeze', 'Strong password'],
  kid: `<p><strong>Identity theft</strong> is when someone uses your personal information to steal money or open accounts in your name.</p><p>Watch out for <strong>phishing</strong>: fake texts or emails pretending to be your bank or a game company, asking for passwords or codes.</p><p>Never share your passwords, Social Security number or login codes. Use strong, different passwords and turn on two-step login.</p>`,
  adult: `<p><strong>Identity theft</strong> happens when someone uses your personal information (Social Security number, account numbers, logins) to commit fraud. <strong>Phishing</strong> messages impersonate trusted companies to steal credentials; real banks won't ask for your password or one-time codes.</p><p>Protection: unique strong passwords and two-factor authentication, shredding documents, checking statements and credit reports, and a free <strong>credit freeze</strong> at all three bureaus, which blocks new accounts in your name. Report theft at IdentityTheft.gov.</p>`,
  quiz: [{ q: 'You get a text: "Your bank account is locked. Reply with your password." What is it?', o: ['Phishing, a scam', 'A real bank message', 'A prize'], why: 'Banks never ask for your password by text.' },
         { q: 'A free tool that stops anyone from opening new credit in your name is a…', o: ['Credit freeze', 'Debit card', 'Overdraft'], why: 'A credit freeze blocks new accounts until you lift it.' }] },
{ id: 'bins', world: 10, boss: true, title: 'Boss: The Scam Shark', pool: ['ins1', 'ins2', 'ins3', 'ins4'] },

/* ---------------- World 11: Future Falls ---------------- */
{ id: 'fut1', world: 11, title: 'Paying for college', sol: ['EPF.18'], terms: ['FAFSA', 'Grant', 'Scholarship', 'Student loan'],
  kid: `<p>College and training programs cost money, but there are many ways to pay.</p><p><strong>Grants</strong> and <strong>scholarships</strong> are free money you don't pay back. <strong>Student loans</strong> must be paid back with interest.</p><p>The <strong>FAFSA</strong> is the free form that unlocks most financial aid. Fill it out every year, and never pay a company to "find" scholarships.</p>`,
  adult: `<p>Funding sources, best first: <strong>grants</strong> and <strong>scholarships</strong> (no repayment), work-study and savings, then federal <strong>student loans</strong>, and private loans last. The <strong>FAFSA</strong> (Free Application for Federal Student Aid) determines eligibility for federal grants, work-study and federal loans, and many states and schools use it too.</p><p>Federal loans offer fixed rates and income-driven repayment options that private loans may not. Scholarship scams charge fees or guarantee awards; legitimate scholarships don't charge you to apply.</p>`,
  quiz: [{ q: 'Which college aid do you NOT have to pay back?', o: ['Grants and scholarships', 'Federal student loans', 'Private student loans'], why: 'Grants and scholarships are gift aid.' },
         { q: 'A website charges $99 to "guarantee" you a scholarship. This is most likely…', o: ['A scam', 'The FAFSA', 'A grant'], why: 'Legitimate scholarships don’t charge fees or guarantee awards, and the FAFSA is free.' }] },
{ id: 'fut2', world: 11, title: 'Saving early: 529 plans', sol: ['EPF.17', 'EPF.18'], terms: ['529 plan', 'Virginia529', 'Tax-advantaged', 'Return on investment'],
  kid: `<p>A <strong>529 plan</strong> is a special savings account for school. Virginia's is called <strong>Virginia529</strong>.</p><p>Money in it can grow without being taxed, as long as it's spent on education.</p><p>Before choosing a program, compare the cost with the jobs and pay it can lead to. That's the program's <strong>return on investment</strong>.</p>`,
  adult: `<p><strong>529 plans</strong> are <strong>tax-advantaged</strong> education savings accounts: growth is tax-free when used for qualified education costs. <strong>Virginia529</strong> is the state's program, and Virginia offers a state income tax deduction for contributions within limits.</p><p>Think about education as an investment: compare total cost and likely debt with expected earnings in that field. There are multiple pathways: community college, apprenticeships, industry credentials, the military and four-year degrees.</p>`,
  quiz: [{ q: 'Virginia’s tax-advantaged savings plan for education is called…', o: ['Virginia529', 'The W-4', 'FDIC', 'A 401(k)'], why: 'Virginia529 is the state’s 529 education savings program.' },
         { q: 'Comparing a program’s cost with the income it can lead to is thinking about its…', o: ['Return on investment', 'Overdraft fee', 'Deductible'], why: 'Return on investment weighs what you put in against what you get back.' }] },
{ id: 'fut3', world: 11, title: 'Renting your first place', sol: ['EPF.11', 'EPF.10'], terms: ['Lease', 'Security deposit', 'Utilities', 'Rent vs. buy'],
  kid: `<p>When you rent an apartment, you sign a <strong>lease</strong>, a contract that says how much rent you pay and for how long.</p><p>You usually pay a <strong>security deposit</strong> at the start. You get it back if you leave the place in good shape.</p><p>Remember the extra costs: <strong>utilities</strong> like electricity, water and internet.</p>`,
  adult: `<p>A <strong>lease</strong> is a legal contract: rent, length, rules, who pays which utilities, and penalties for breaking it. Expect a <strong>security deposit</strong> and possibly application fees; landlords often check credit and want rent around 30% of gross income or less.</p><p>Renting offers flexibility and fewer maintenance costs. Buying builds equity but requires a down payment, closing costs, property taxes, insurance and upkeep. Budget for <strong>utilities</strong> and renters insurance on top of rent.</p>`,
  quiz: [{ q: 'The money you pay at move-in and get back if the apartment is undamaged is the…', o: ['Security deposit', 'Premium', 'Utility bill'], why: 'A security deposit protects the landlord against damage.' },
         { q: 'A lease is…', o: ['A legal contract for renting', 'A type of insurance', 'A savings account'], why: 'A lease spells out the terms of renting.' }] },
{ id: 'fut4', world: 11, title: 'Your first car', sol: ['EPF.11', 'EPF.13'], terms: ['Total cost of ownership', 'Lease vs. buy', 'Depreciation', 'Down payment'],
  kid: `<p>A car costs more than its price tag. You also pay for gas, insurance, repairs and registration. Together that's the <strong>total cost of ownership</strong>.</p><p>Cars lose value over time. That's called <strong>depreciation</strong>.</p><p>You can <strong>buy</strong> a car (you own it) or <strong>lease</strong> it (you rent it for a few years and give it back).</p>`,
  adult: `<p><strong>Total cost of ownership</strong> includes the purchase price or payments, interest, insurance, fuel, maintenance, repairs, taxes and registration. New cars <strong>depreciate</strong> quickly, often losing a large share of value in the first few years, which is why a reliable used car is often the smarter buy.</p><p><strong>Leasing</strong> means lower payments and a newer car, but mileage limits and no ownership at the end. A larger <strong>down payment</strong> and shorter loan reduce total interest. Get pre-approved by a bank or credit union before visiting a dealer.</p>`,
  quiz: [{ q: 'Which costs are part of owning a car?', o: ['Payments, insurance, gas and repairs', 'Only the sticker price', 'Only gas'], why: 'Total cost of ownership includes every cost of running the car.' },
         { q: 'A car loses value as it gets older. This is called…', o: ['Depreciation', 'Appreciation', 'Compound interest'], why: 'Depreciation is the drop in value over time.' }] },
{ id: 'fut5', world: 11, title: 'From pretend to real', sol: ['EPF.16', 'EPF.17'], terms: ['Custodial account', 'Roth IRA', 'Index fund', 'Paying yourself first'],
  kid: `<p>You practiced with pretend money in Bullsburg. Here's how to do it for real:</p><p><strong>1.</strong> Open a savings account (a teen account with a parent at a bank or credit union). <strong>2.</strong> With your first paycheck, <strong>pay yourself first</strong>: move some to savings before spending. <strong>3.</strong> Under 18? A grown-up can open a <strong>custodial account</strong> so you can invest. Teens with job income can even have a <strong>Roth IRA</strong>.</p>`,
  adult: `<p>Turning practice into habits: open a youth or student savings account; automate "<strong>pay yourself first</strong>" transfers on payday; build the emergency fund; then invest for the long term, often through low-cost, diversified <strong>index funds</strong>.</p><p>Minors can invest through a <strong>custodial account</strong> managed by an adult. Anyone with earned income, including teens, can contribute to a <strong>Roth IRA</strong> up to their earnings (within the annual limit), and qualified withdrawals in retirement are tax-free. Start small; time and consistency matter more than the amount.</p>`,
  quiz: [{ q: '"Paying yourself first" means…', o: ['Moving money to savings before you spend', 'Buying yourself something nice first', 'Paying bills late'], why: 'Saving first makes it automatic instead of whatever is left over.' },
         { q: 'You’re 16 with a part-time job. How can you start investing?', o: ['A custodial account or Roth IRA with a parent’s help', 'You legally can’t learn about money until 18', 'Only by buying lottery tickets'], why: 'Minors invest through custodial accounts, and earned income allows a Roth IRA.' }] },
{ id: 'bfut', world: 11, boss: true, title: 'Boss: The Future Fog', pool: ['fut1', 'fut2', 'fut3', 'fut4', 'fut5'] }
];

